/**
 * Service worker — cache-first with a precached shell.
 *
 * On install, the worker fetches and caches every page the site ships. Every
 * request then hits the cache first; a network fetch runs in the background and
 * updates the cache for the next visit (stale-while-revalidate). If the network
 * is unreachable, the cached version still works.
 *
 * The precache list below is the build output manifest. It is regenerated by
 * `scripts/sitemap.mjs` on each build from the files actually in `out/`.
 */
const CACHE = "smc-v1";

const PRECACHE = [
  "/",
  "/recommendation/",
  "/tools/mortgage-deep-dive/",
  "/tools/debt-payoff/",
  "/tools/refinance-break-even/",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE))
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter((key) => key !== CACHE).map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  // Only handle navigation and same-origin requests — skip CDN / cross-origin.
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;
  if (event.request.method !== "GET") return;

  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(event.request).then((cached) => {
        const fetched = fetch(event.request).then((response) => {
          if (response.ok) cache.put(event.request, response.clone());
          return response;
        });
        return cached || fetched;
      })
    )
  );
});
